export const LIVE_LIMIT = EFFECT_LIVE_LIMIT;   // shared with every animated text effect on the page (effects-budget.js)
export const TARGET_FPS = 30;                  // the package's frame cap
export const START_TIME = 6.5;                 // the package's starting moment (crystals forming) - also its reduced-motion still frame
const MAX_W = 1536, MAX_H = 640;               // render resolution of one text: the package's master camera
