const jobs = new Map();
const reduced = typeof matchMedia === "function" ? matchMedia("(prefers-reduced-motion: reduce)") : null;
const observer = typeof IntersectionObserver === "function" ? new IntersectionObserver(seen => { for (const item of seen) { const entry = item.target.__ice; if (entry) { entry.visible = item.isIntersecting; if (entry.visible) entry.dirty = true; } } }, { threshold: 0 }) : null;

